{
  "title": "社团活动",
  "scene": "小雅是学生会的宣传部长，今天社团要在学校礼堂举办一场文化节活动。小雅必须在下午4点前确认所有准备工作是否就绪。她走过摆放着宣传海报和装饰品的展台时，注意到几份海报上的日期被涂改过，时间紧迫，她需要快速做出决策。",
  "goal": "确保文化节活动能够顺利进行",
  "clue": "被涂改的日期在宣传海报上",
  "choices": [
    {
      "id": "A",
      "text": "仔细检查所有海报确认日期",
      "outcome": "成功查出所有日期的错误，并重新粘贴正确的海报。确认无误后，活动准备就绪。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "去找老师帮忙检查",
      "outcome": "老师很快检查完，但发现几份海报的日期确实有误。活动准备工作因及时修正而有惊无险地进行。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "忽略涂改部分，认为是小失误",
      "outcome": "小雅决定忽略涂改的日期，继续工作。但因为日期错误导致部分物资准备滞后，幸好及时发现并补救，活动准备工作得以继续。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
